<?php if(in_array($enrollRole,array('owner','super_admin','admin','manager'),TRUE)): ?><section class="lc-card"><details><summary>Aktifkan portal untuk penghuni existing</summary><p class="muted">Pilih penghuni aktif/reservasi yang belum memiliki portal. Upload KTP terbaru wajib. Masa tinggal dan transaksi existing tetap menjadi sumber administrasi.</p><form method="post" action="<?= base_url('lifecycle/enroll'); ?>" enctype="multipart/form-data" data-lc-form><div class="lc-fields"><label>Masa tinggal existing<select name="stay_id" required><option value="">Pilih penghuni</option><?php foreach(isset($enroll_stays)?$enroll_stays:array() as $stay): ?><option value="<?= (int)$stay['id']; ?>"><?= gh_lc_e(gh_lc_v($stay,'label',trim(gh_lc_v($stay,'fullname','').' · '.gh_lc_v($stay,'room_label','Masa tinggal #'.$stay['id'])))); ?></option><?php endforeach; ?></select></label><label>KTP terbaru *<input type="file" name="ktp_file" accept=".pdf,.jpg,.jpeg,.png" required><span class="lc-help">PDF/JPG/PNG, maksimal 10 MB.</span></label><label>Buku nikah (opsional)<input type="file" name="marriage_file" accept=".pdf,.jpg,.jpeg,.png"></label></div><button type="submit">Aktifkan portal penghuni existing</button></form></details></section><?php endif; ?>
